11	// runRegisterWith runs runRegister with the given stdin and captured stdout.
12	func runRegisterWith(t *testing.T, input string) (string, int) {
13		t.Helper()
14		oldStdin := os.Stdin
15		oldStdout := os.Stdout
16		defer func() {
17			os.Stdin = oldStdin
18			os.Stdout = oldStdout
19		}()
20		inR, inW, err := os.Pipe()
21		if err != nil {
22			t.Fatalf("pipe: %v", err)
23		}
24		os.Stdin = inR
25		go func() {
26			defer inW.Close()
27			_, _ = inW.WriteString(input)
28		}()
29		outR, outW, err := os.Pipe()
30		if err != nil {
31			t.Fatalf("pipe: %v", err)
32		}
33		os.Stdout = outW
34		code := runRegister()
35		outW.Close()
36		var buf bytes.Buffer
37		if _, err := buf.ReadFrom(outR); err != nil {
38			t.Fatalf("read stdout: %v", err)
39		}
40		return buf.String(), code
41	}
