43	func TestRegisterSuccess(t *testing.T) {
44		input := `{"requests":[
45			{"service":"b","expectedRevision":0,"instances":[{"id":"b2","address":"h2:2"},{"id":"b1","address":"h1:1"}]},
46			{"service":"b","expectedRevision":1,"instances":[{"id":"b1","address":"h1:1"},{"id":"b2","address":"h2:2"}]},
47			{"service":"a","expectedRevision":0,"instances":[]}
48		]}`
49		out, code := runRegisterWith(t, input)
50		if code != 0 {
51			t.Fatalf("exit code: %d, output: %s", code, out)
52		}
53		var got registerOutput
54		if err := json.Unmarshal([]byte(out), &got); err != nil {
55			t.Fatalf("output is not JSON: %v\n%s", err, out)
56		}
57		if len(got.Results) != 3 {
58			t.Fatalf("results: %+v", got.Results)
59		}
60		want := []registerResult{
61			{Service: "b", OK: true, Changed: true, Revision: 1},
62			{Service: "b", OK: true, Changed: false, Revision: 1},
63			{Service: "a", OK: true, Changed: true, Revision: 1},
64		}
65		for i := range want {
66			if got.Results[i] != want[i] {
67				t.Fatalf("result %d: got %+v want %+v", i, got.Results[i], want[i])
68			}
69		}
70		// Services sorted by name; instances sorted by id; empty list kept.
71		if len(got.Services) != 2 {
72			t.Fatalf("services: %+v", got.Services)
73		}
74		if got.Services[0].Service != "a" || got.Services[0].Revision != 1 || len(got.Services[0].Instances) != 0 {
75			t.Fatalf("service a: %+v", got.Services[0])
76		}
77		if got.Services[1].Service != "b" || got.Services[1].Revision != 1 {
78			t.Fatalf("service b: %+v", got.Services[1])
79		}
80		insts := got.Services[1].Instances
81		if len(insts) != 2 || insts[0].ID != "b1" || insts[0].Address != "h1:1" || insts[1].ID != "b2" {
82			t.Fatalf("service b instances: %+v", insts)
83		}
84	}
