86	func TestRegisterFailuresDoNotAbort(t *testing.T) {
87		input := `{"requests":[
88			{"service":"a","expectedRevision":0,"instances":[{"id":"x","address":"h:1"}]},
89			{"service":"a","expectedRevision":5,"instances":[{"id":"y","address":"h:2"}]},
90			{"service":"a","expectedRevision":1,"instances":[{"id":"y","address":"h:2"}]},
91			{"service":"a","expectedRevision":2,"instances":[{"id":"","address":"h:1"}]},
92			{"service":"a","expectedRevision":2,"instances":[{"id":"z","address":"nope"}]},
93			{"service":"b","expectedRevision":1,"instances":[]}
94		]}`
95		out, code := runRegisterWith(t, input)
96		if code != 1 {
97			t.Fatalf("exit code: %d", code)
98		}
99		var got registerOutput
100		if err := json.Unmarshal([]byte(out), &got); err != nil {
101			t.Fatalf("output is not JSON: %v\n%s", err, out)
102		}
103		if len(got.Results) != 6 {
104			t.Fatalf("results: %+v", got.Results)
105		}
106		// 0: create
107		if r := got.Results[0]; !r.OK || !r.Changed || r.Revision != 1 {
108			t.Fatalf("result 0: %+v", r)
109		}
110		// 1: conflict, expected 5 actual 1
111		if r := got.Results[1]; r.OK || r.Error != "conflict" || r.ExpectedRevision != 5 || r.ActualRevision != 1 || r.Revision != 1 {
112			t.Fatalf("result 1: %+v", r)
113		}
114		// 2: update to rev 2
115		if r := got.Results[2]; !r.OK || !r.Changed || r.Revision != 2 {
116			t.Fatalf("result 2: %+v", r)
117		}
118		// 3: invalid content with a matching revision: still invalid, list untouched
119		if r := got.Results[3]; r.OK || r.Error != "invalid" || r.Revision != 2 {
120			t.Fatalf("result 3: %+v", r)
121		}
122		// 4: invalid address
123		if r := got.Results[4]; r.OK || r.Error != "invalid" || r.Revision != 2 {
124			t.Fatalf("result 4: %+v", r)
125		}
126		// 5: conflict on a brand-new service
127		if r := got.Results[5]; r.OK || r.Error != "conflict" || r.ExpectedRevision != 1 || r.ActualRevision != 0 || r.Revision != 0 {
128			t.Fatalf("result 5: %+v", r)
129		}
130		// Only the successful registrations are reflected.
131		if len(got.Services) != 1 || got.Services[0].Service != "a" || got.Services[0].Revision != 2 {
132			t.Fatalf("services: %+v", got.Services)
133		}
134		if len(got.Services[0].Instances) != 1 || got.Services[0].Instances[0].ID != "y" {
135			t.Fatalf("instances: %+v", got.Services[0].Instances)
136		}
137	}
