242		want := []registerResult{
243			{Service: "svc", OK: true, Changed: true, Revision: 1},
244			{Service: "svc", OK: true, Changed: true, Revision: 1, Sequence: 1},
245			{Service: "svc", OK: true, Changed: true, Revision: 1, Sequence: 1},
