289	func TestHealthFailures(t *testing.T) {
290		input := `{"requests":[
291			{"service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h:1"}]},
292			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":5,"healthy":true},
293			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":3,"healthy":true},
294			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":5,"healthy":false,"reason":"different"},
295			{"type":"health","service":"svc","instanceId":"ghost","expectedRevision":1,"sequence":1,"healthy":true},
296			{"type":"health","service":"svc","instanceId":"a","expectedRevision":2,"sequence":6,"healthy":true},
297			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":6,"healthy":true}
298		]}`
299		out, code := runRegisterWith(t, input)
300		if code != 1 {
301			t.Fatalf("exit code: %d", code)
302		}
303		var got registerOutput
304		if err := json.Unmarshal([]byte(out), &got); err != nil {
305			t.Fatalf("output is not JSON: %v", err)
306		}
307		if len(got.Results) != 7 {
308			t.Fatalf("results: %+v", got.Results)
309		}
310		// 0: create
311		if r := got.Results[0]; !r.OK || r.Revision != 1 {
312			t.Fatalf("result 0: %+v", r)
313		}
314		// 1: healthy seq 5
315		if r := got.Results[1]; !r.OK || !r.Changed || r.Sequence != 5 {
316			t.Fatalf("result 1: %+v", r)
317		}
318		// 2: stale (3 < 5)
319		if r := got.Results[2]; r.OK || r.Error != "stale" || r.Sequence != 5 {
320			t.Fatalf("result 2: %+v", r)
321		}
322		// 3: same seq 5, different content -> conflict
323		if r := got.Results[3]; r.OK || r.Error != "conflict" || r.Sequence != 5 {
324			t.Fatalf("result 3: %+v", r)
325		}
326		// 4: instance missing -> not_found
327		if r := got.Results[4]; r.OK || r.Error != "not_found" || r.Revision != 1 {
328			t.Fatalf("result 4: %+v", r)
329		}
330		// 5: wrong revision -> conflict
331		if r := got.Results[5]; r.OK || r.Error != "conflict" || r.ExpectedRevision != 2 || r.ActualRevision != 1 {
332			t.Fatalf("result 5: %+v", r)
333		}
334		// 6: healthy seq 6 succeeds (state still healthy from result 1)
335		if r := got.Results[6]; !r.OK || !r.Changed || r.Sequence != 6 {
336			t.Fatalf("result 6: %+v", r)
337		}
338	}
