792		}
793		// First select takes the smallest healthy id.
794		if r := got.Results[3]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 5 || r.Revision != 1 {
795			t.Fatalf("first select: %+v", r)
