1265	// changes i1's address, which also must not take effect.
1266	func TestRejectedConflictReplacementKeepsRotationPosition(t *testing.T) {
1267		input := `{"requests":[
1268			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"},{"id":"i2","address":"h2:8080"}]},
1269			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":11,"healthy":true},
1270			{"type":"health","service":"svc","instanceId":"i2","expectedRevision":1,"sequence":22,"healthy":true},
1271			{"type":"select","service":"svc","expectedRevision":1},
1272			{"type":"register","service":"svc","expectedRevision":7,"instances":[{"id":"i1","address":"hx:8080"},{"id":"i2","address":"h2:8080"}]},
1273			{"type":"select","service":"svc","expectedRevision":1}
1274		]}`
1275		out, code := runRegisterWith(t, input)
1276		if code != 1 {
1277			t.Fatalf("batch contains a failure, exit code: %d, output: %s", code, out)
1278		}
1279		var got registerOutput
1280		if err := json.Unmarshal([]byte(out), &got); err != nil {
1281			t.Fatalf("output is not JSON: %v\n%s", err, out)
1282		}
1283		if len(got.Results) != 6 {
1284			t.Fatalf("results: %+v", got.Results)
1285		}
1286		if r := got.Results[3]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 11 {
1287			t.Fatalf("first select: %+v", r)
1288		}
1289		if r := got.Results[4]; r.OK || r.Error != "conflict" ||
1290			r.Revision != 1 || r.ExpectedRevision != 7 || r.ActualRevision != 1 {
1291			t.Fatalf("conflicting replacement: %+v", r)
1292		}
1293		// The conflict left the cursor just after i1: i2 is next, not i1 again.
1294		if r := got.Results[5]; !r.OK || r.InstanceID != "i2" || r.Address != "h2:8080" || r.Sequence != 22 || r.Revision != 1 {
1295			t.Fatalf("select after conflict must continue at i2 with its original state: %+v", r)
1296		}
1297		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
1298			t.Fatalf("services: %+v", got.Services)
1299		}
1300		if insts := got.Services[0].Instances; len(insts) != 2 ||
1301			insts[0].ID != "i1" || insts[0].Address != "h1:8080" || insts[0].Health != "healthy" || insts[0].Sequence != 11 ||
1302			insts[1].ID != "i2" || insts[1].Address != "h2:8080" || insts[1].Health != "healthy" || insts[1].Sequence != 22 {
1303			t.Fatalf("final list must keep only accepted state: %+v", insts)
1304		}
1305	}
