1307	// TestRejectedInvalidReplacementKeepsRotationPosition is the invalid-content
1308	// counterpart: the malformed replacement follows the first successful
1309	// selection immediately, so the next select must still move to i2 rather than
1310	// repeating i1, and the valid prefix changing i1's address must not apply.
1311	func TestRejectedInvalidReplacementKeepsRotationPosition(t *testing.T) {
1312		input := `{"requests":[
1313			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"},{"id":"i2","address":"h2:8080"}]},
1314			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":11,"healthy":true},
1315			{"type":"health","service":"svc","instanceId":"i2","expectedRevision":1,"sequence":22,"healthy":true},
1316			{"type":"select","service":"svc","expectedRevision":1},
1317			{"type":"register","service":"svc","expectedRevision":7,"instances":[{"id":"i1","address":"h9:8080"},{"id":"i2","address":"bad-address"}]},
1318			{"type":"select","service":"svc","expectedRevision":1}
