1367			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":3,"healthy":true},
1368			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s1"},
1369			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s1"},
1370			{"type":"select","service":"svc","expectedRevision":1},
1371			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"  s1  "},
1372			{"type":"select","service":"svc","expectedRevision":1}
