1394		// move the cursor.
1395		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Sequence != 2 {
1396			t.Fatalf("plain select after reuse: %+v", r)
1397		}
1398		// 7: the padded key trims to the same session and still reuses a.
1399		if r := got.Results[7]; !r.OK || r.InstanceID != "a" {
1400			t.Fatalf("padded key should reuse the same session: %+v", r)
