1503			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":1,"healthy":true},
1504			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":1,"healthy":true},
1505			{"type":"select","service":"svc","expectedRevision":99,"sessionKey":"  "},
